/// Point doubling on NIST curve P-521 in Jacobian coordinates
///
///
/// Does p3 := 2 * p1 where all points are regarded as Jacobian triples.
/// A Jacobian triple (x,y,z) represents affine point (x/z^2,y/z^3).
/// It is assumed that all coordinates of the input point are fully
/// reduced mod p_521 and that the z coordinate is not zero.
pub(crate) fn p521_jdouble_alt(p3: &mut [u64; 27], p1: &[u64; 27]) {
    // SAFETY: inline assembly. see [crate::low::inline_assembly_safety] for safety info.
    unsafe {
        core::arch::asm!(

        Q!("    endbr64         " ),

        // Save registers and make room on stack for temporary variables

        Q!("    push            " "rbx"),
        Q!("    push            " "rbp"),
        Q!("    push            " "r12"),
        Q!("    push            " "r13"),
        Q!("    push            " "r14"),
        Q!("    push            " "r15"),

        Q!("    sub             " "rsp, " NSPACE!()),

        // Main code, just a sequence of basic field operations

        // z2 = z^2
        // y2 = y^2

        sqr_p521!(z2!(), z_1!()),
        sqr_p521!(y2!(), y_1!()),

        // x2p = x^2 - z^4 = (x + z^2) * (x - z^2)

        add_p521!(t1!(), x_1!(), z2!()),
        sub_p521!(t2!(), x_1!(), z2!()),
        mul_p521!(x2p!(), t1!(), t2!()),

        // t1 = y + z
        // x4p = x2p^2
        // xy2 = x * y^2

        add_p521!(t1!(), y_1!(), z_1!()),
        sqr_p521!(x4p!(), x2p!()),
        weakmul_p521!(xy2!(), x_1!(), y2!()),

        // t2 = (y + z)^2

        sqr_p521!(t2!(), t1!()),

        // d = 12 * xy2 - 9 * x4p
        // t1 = y^2 + 2 * y * z

        cmsub_p521!(d!(), "12", xy2!(), "9", x4p!()),
        sub_p521!(t1!(), t2!(), z2!()),

        // y4 = y^4

        sqr_p521!(y4!(), y2!()),

        // z_3' = 2 * y * z
        // dx2 = d * x2p

        sub_p521!(z_3!(), t1!(), y2!()),
        weakmul_p521!(dx2!(), d!(), x2p!()),

        // x' = 4 * xy2 - d

        cmsub41_p521!(x_3!(), xy2!(), d!()),

        // y' = 3 * dx2 - 8 * y4

        cmsub38_p521!(y_3!(), dx2!(), y4!()),

        // Restore stack and registers

        Q!("    add             " "rsp, " NSPACE!()),
        Q!("    pop             " "r15"),
        Q!("    pop             " "r14"),
        Q!("    pop             " "r13"),
        Q!("    pop             " "r12"),
        Q!("    pop             " "rbp"),
        Q!("    pop             " "rbx"),

        inout("rdi") p3.as_mut_ptr() => _,
        inout("rsi") p1.as_ptr() => _,
        // clobbers
        out("r10") _,
        out("r11") _,
        out("r12") _,
        out("r13") _,
        out("r14") _,
        out("r15") _,
        out("r8") _,
        out("r9") _,
        out("rax") _,
        out("rcx") _,
        out("rdx") _,
            )
    };
}
